insert into tap_results select lives_ok($$select public.agri_command('save_credit_contact',pg_temp.contact())$$,'Save client details without limit, terms or approval');
insert into tap_results select is(public.agri_command('save_credit_contact',pg_temp.contact())->>'duplicate','true','Contact save retries exactly once');
insert into tap_results select throws_ok($$select public.agri_command('save_credit_contact',pg_temp.contact()||'{"name":"TEST different"}')$$,'P0001','Credit request ID conflict','Retry cannot change original contact data');
insert into tap_results select throws_ok($$select public.agri_command('save_credit_contact',pg_temp.contact()||jsonb_build_object('requestId',pg_temp.i(702)))$$,'P0001','Client details changed. Refresh before saving','Stale contact edits are rejected');
insert into tap_results select throws_ok($$select public.agri_command('record_credit_sale',pg_temp.sale())$$,'P0001','Open or renew your own authorized shift online before changing credit','Removing limits does not remove the shift requirement');
insert into tap_results select throws_ok($$select public.agri_command('save_credit_contact',pg_temp.contact()||jsonb_build_object('requestId',pg_temp.i(702)))$$,'42501','Only the owner can add or edit clients','Cashier cannot alter client directory');
insert into tap_results select is((select count(*) from public.stock_control_events where action='save_credit_contact'),0::bigint,'Contact event does not leak to stock-only staff');
insert into tap_results select is((select count(*) from public.audit_events where action='save_credit_contact'),0::bigint,'Contact audit does not leak to stock-only staff');
insert into tap_results select lives_ok($$select public.agri_command('record_credit_sale',pg_temp.sale(901,90))$$,'Zero-limit client with default legacy terms can buy on 90 days');
insert into tap_results select is(public.agri_command('record_credit_sale',pg_temp.sale(901,90))->>'duplicate','true','Unrestricted credit still prevents duplicate sales');
insert into tap_results select is((select c->>'unconfirmedInvoices' from jsonb_array_elements(pg_temp.book()->'clients') c where c->>'name'='TEST imported'),'1','Client warning counts unknown dates across the whole account');
insert into tap_results select is((select c->>'overdue' from jsonb_array_elements(pg_temp.book()->'clients') c where c->>'name'='TEST imported'),'100000','Existing overdue debt remains visible');
insert into tap_results select lives_ok($$select public.agri_command('record_credit_sale',pg_temp.sale(902,60)||jsonb_build_object('clientId',pg_temp.imported()))$$,'Imported client can buy despite zero limit, overdue debt and an unknown historical date');
insert into tap_results select lives_ok($$select public.agri_command('record_credit_sale',pg_temp.sale(903,30))$$,'30-day term remains available');
insert into tap_results select throws_ok($$select public.agri_command('record_credit_sale',pg_temp.sale(904,45))$$,'P0001','Choose 30, 60 or 90 calendar days','Other term values stay invalid');
insert into tap_results select throws_ok($$select public.agri_command('record_credit_sale',pg_temp.sale(904,60)||'{"cashReceived":100000}')$$,'P0001','Credit requires a valid total and a smaller cash payment; use cash checkout for full payment','Full payment uses cash checkout instead of zero debt');
insert into tap_results select throws_ok($$select public.agri_command('record_credit_sale',pg_temp.sale(904,60)||'{"officialReference":"TEST-BOOK-901"}')$$,'P0001','This official booklet invoice reference is already recorded','Invoice reference protection stays in place');
insert into tap_results select is(pg_temp.book()->>'outstanding','390000','Opening debt and three unpaid sale balances add exactly');
insert into tap_results select is((select count(*) from public.sales),3::bigint,'Exactly three new sales');
insert into tap_results select is((select sum(amount) from public.payments),60000::numeric,'Only actual down payments enter the drawer');
insert into tap_results select is((select quantity from public.branch_inventory),70::numeric,'Stock reduced exactly once per sale');
insert into tap_results select is((select count(*) from public.credit_clients where enabled or credit_limit<>0),0::bigint,'No legacy limits or approval flags were invented');
insert into tap_results select is((select sum(amount) from public.credit_invoices where source='opening'),150000::numeric,'Original opening balances remain unchanged');
insert into tap_results select is((select count(*) from public.credit_invoices where source='opening' and (due_on is not null or term is not null)),0::bigint,'Historical source dates and terms remain unknown');
